import { requireVendorSession } from "../../../../../lib/vendor-session";
import { createVendorProductDraft, vendorCatalogWorkspace } from "../../../../../lib/vendor-backoffice-service";
export async function POST(request:Request){try{const p=await requireVendorSession(request,true);const b=await request.json() as Record<string,unknown>;const text=(k:string)=>typeof b[k]==="string"?String(b[k]).trim():"";await createVendorProductDraft(p,{title:text("title"),categoryCode:text("categoryCode"),vendorSku:text("vendorSku")||undefined,brand:text("brand")||undefined,model:text("model")||undefined,gtin:text("gtin")||undefined,supplierUnitPriceMinor:Number(b.supplierUnitPriceMinor),stockOnHand:Number(b.stockOnHand),safetyStock:Number(b.safetyStock??0),adviceAvailable:b.adviceAvailable!==false});return Response.json(await vendorCatalogWorkspace(p));}catch(e){return Response.json({error:e instanceof Error?e.message:"catalog_create_failed"},{status:400})}}
